CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(160) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','CLOSED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE vehicles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), plate_number VARCHAR(32) NOT NULL, display_name VARCHAR(120), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, plate_number), UNIQUE (tenant_id, id));
CREATE TABLE devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), device_uid VARCHAR(96) NOT NULL UNIQUE, hardware_type VARCHAR(32) NOT NULL CHECK (hardware_type IN ('ANDROID_HEADUNIT','ESP32_GNSS','GPS_4G_TERMINAL','OTHER')), status VARCHAR(24) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','ACTIVE','DISABLED','REVOKED')), credential_hash TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, id));
CREATE TABLE device_bindings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, device_id UUID NOT NULL, vehicle_id UUID NOT NULL, bound_at TIMESTAMPTZ NOT NULL DEFAULT now(), unbound_at TIMESTAMPTZ, FOREIGN KEY (tenant_id, device_id) REFERENCES devices(tenant_id, id), FOREIGN KEY (tenant_id, vehicle_id) REFERENCES vehicles(tenant_id, id));
CREATE UNIQUE INDEX uq_active_device_binding ON device_bindings(device_id) WHERE unbound_at IS NULL;
CREATE UNIQUE INDEX uq_active_vehicle_binding ON device_bindings(vehicle_id) WHERE unbound_at IS NULL;
CREATE TABLE gps_locations (id BIGSERIAL PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenants(id), device_id UUID NOT NULL REFERENCES devices(id), event_id UUID NOT NULL, recorded_at TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), position GEOGRAPHY(POINT, 4326) NOT NULL, speed_kmh NUMERIC(7,2) CHECK (speed_kmh IS NULL OR speed_kmh >= 0), heading_degrees NUMERIC(6,2) CHECK (heading_degrees IS NULL OR (heading_degrees >= 0 AND heading_degrees < 360)), altitude_m NUMERIC(9,2), satellites SMALLINT CHECK (satellites IS NULL OR satellites >= 0), accuracy_m NUMERIC(8,2) CHECK (accuracy_m IS NULL OR accuracy_m >= 0), ignition_on BOOLEAN, UNIQUE (device_id, event_id));
CREATE INDEX ix_gps_locations_tenant_recorded ON gps_locations(tenant_id, recorded_at DESC);
CREATE INDEX ix_gps_locations_device_recorded ON gps_locations(device_id, recorded_at DESC);
CREATE INDEX ix_gps_locations_position ON gps_locations USING GIST(position);
